// Hand-written. Not generated by Speakeasy.
//
// Guards which attributes are concealed from console output.
//
// Review found service jwks and authentication_callback_api_secret printing in
// plan output and CI logs. The JWK Sets are the serious case: service.jwks must
// contain public/private key pairs for asymmetric ID token signing, and
// credential_jwks is documented as holding private keys. A leaked client secret
// compromises one application; a leaked service signing key lets someone mint
// tokens for every client under that authorization server.
//
// Sensitive keeps these out of plan output, `terraform state show` and CI logs.
// It does not remove them from state, which is a separate and larger piece of
// work (ephemeral resources, ENG-5904).
//
// These live in the overlay as x-speakeasy-param-sensitive, so a regeneration
// or an overlay edit could silently drop them. Nothing else would notice: the
// provider would build and every other test would pass.
package provider

import (
	"context"
	"testing"

	"github.com/hashicorp/terraform-plugin-framework/datasource"
	"github.com/hashicorp/terraform-plugin-framework/resource"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema"
)

// mustConceal lists every attribute that carries secret material, with the
// overlay property that marks it.
var mustConceal = map[string]map[string]string{
	"authlete_service": {
		"api_secret":                         "apiSecret",
		"jwks":                               "jwks",
		"federation_jwks":                    "federationJwks",
		"credential_jwks":                    "credentialJwks",
		"authentication_callback_api_secret": "authenticationCallbackApiSecret",
		"developer_authentication_callback_api_secret": "developerAuthenticationCallbackApiSecret",
	},
	"authlete_client": {
		"client_secret": "clientSecret",
	},
}

func isSensitive(attr schema.Attribute) bool {
	return attr.IsSensitive()
}

func TestSecretsAreConcealedOnResources(t *testing.T) {
	for name, res := range map[string]resource.Resource{
		"authlete_service": NewServiceResource(),
		"authlete_client":  NewClientResource(),
	} {
		attrs := resourceSchema(t, res).Attributes
		for attrName, specProperty := range mustConceal[name] {
			attr, ok := attrs[attrName]
			if !ok {
				t.Errorf("%s has no %q attribute; update this test or the overlay", name, attrName)
				continue
			}
			if !isSensitive(attr) {
				t.Errorf("%s.%s is not marked sensitive, so it prints in plan output and CI logs.\n\n"+
					"Restore `x-speakeasy-param-sensitive: true` on the schema property %q in "+
					".speakeasy/terraform_overlay.yaml.", name, attrName, specProperty)
			}
		}
	}
}

// Data sources read the same values back, so they need the same treatment.
func TestSecretsAreConcealedOnDataSources(t *testing.T) {
	for name, ds := range map[string]datasource.DataSource{
		"authlete_service": NewServiceDataSource(),
		"authlete_client":  NewClientDataSource(),
	} {
		resp := &datasource.SchemaResponse{}
		ds.Schema(context.Background(), datasource.SchemaRequest{}, resp)
		if resp.Diagnostics.HasError() {
			t.Fatalf("%s data source schema has errors: %v", name, resp.Diagnostics)
		}
		for attrName, specProperty := range mustConceal[name] {
			attr, ok := resp.Schema.Attributes[attrName]
			if !ok {
				continue // data sources need not expose everything the resource does
			}
			if !attr.IsSensitive() {
				t.Errorf("data source %s.%s is not marked sensitive.\n\n"+
					"Restore `x-speakeasy-param-sensitive: true` on %q in "+
					".speakeasy/terraform_overlay.yaml.", name, attrName, specProperty)
			}
		}
	}
}

// The nested case: sns_credentials is a list of objects whose api_secret is a
// secret. Nested attributes are easy to miss when marking things by hand.
func TestNestedSecretsAreConcealed(t *testing.T) {
	attrs := resourceSchema(t, NewServiceResource()).Attributes
	list, ok := attrs["sns_credentials"].(schema.ListNestedAttribute)
	if !ok {
		t.Skip("sns_credentials is no longer a list of objects; review this test")
	}
	secret, ok := list.NestedObject.Attributes["api_secret"]
	if !ok {
		t.Skip("sns_credentials no longer has api_secret")
	}
	if !secret.IsSensitive() {
		t.Error("sns_credentials[*].api_secret is not marked sensitive.\n\n" +
			"Restore `x-speakeasy-param-sensitive: true` on " +
			"$.components.schemas.sns_credentials.properties.apiSecret in " +
			".speakeasy/terraform_overlay.yaml.")
	}
}

// Documents the deliberate exclusions, so that marking them later is a decision
// rather than an accident, and unmarking the rest cannot be justified by
// pointing at these.
func TestPublicKeySetsAreNotConcealed(t *testing.T) {
	clientAttrs := resourceSchema(t, NewClientResource()).Attributes
	if attr, ok := clientAttrs["jwks"]; ok && attr.IsSensitive() {
		t.Error("client.jwks is marked sensitive.\n\n" +
			"The spec says it `must not include private keys of the client application`, " +
			"so concealing it costs readability for no gain. If Authlete's position on " +
			"that has changed, update this test with the reason.")
	}
}
